<?php
declare(strict_types=1);
namespace EPejabat\Modules\Training;
use EPejabat\Core\{Database,Core,Audit};
final class Attendance {
 public static function session(\PDO $p,int $u,int $programme,array $d):int {ExtendedMigrations::require($p);return Core::tx($p,function()use($p,$u,$programme,$d){$r=Policy::published($p,$programme,true);Policy::require($p,$u,'attendance.manage',$r);if(Database::query($p,"SELECT 1 FROM training_outputs WHERE programme_id=? AND kind='CERTIFICATE' AND status='LOCKED' UNION SELECT 1 FROM training_cpd_records c JOIN training_registrations tr ON tr.id=c.registration_id WHERE tr.programme_id=? AND c.status='APPROVED'",[$programme,$programme])->fetchColumn())throw new \RuntimeException('Final attendance dependencies exist; void/reissue dahulu.');$c=Policy::config($p,$r,true);$start=Workflow::date($d['start_at']??'');$end=Workflow::date($d['end_at']??'');if($start>=$end||$start<$c['start_at']||$end>$c['end_at'])throw new \RuntimeException('Sesi mesti dalam tempoh program.');$policy=[];foreach(['grace_minutes','late_minutes','too_late_minutes','minimum_minutes','early_minutes','checkout_grace_minutes'] as $k){if(!array_key_exists($k,$d))throw new \RuntimeException('Polisi eksplisit diperlukan: '.$k);$policy[$k]=Workflow::number($d[$k],100000);}if($policy['grace_minutes']>$policy['late_minutes']||$policy['late_minutes']>$policy['too_late_minutes']||$policy['minimum_minutes']>(strtotime($end)-strtotime($start))/60)throw new \RuntimeException('Threshold polisi tidak sah.');foreach(['allow_late_completion','allow_too_late_completion'] as $k){if(!isset($d[$k])||!in_array($d[$k],[0,1,'0','1'],true))throw new \RuntimeException('Polisi status diperlukan.');$policy[$k]=(int)$d[$k];}Database::query($p,'INSERT INTO training_sessions(programme_id,title,start_at,end_at,policy_json,created_by) VALUES(?,?,?,?,?,?)',[$programme,Core::text($d['title']??''),$start,$end,Workflow::json($policy),$u]);$id=(int)$p->lastInsertId();Audit::record($p,'attendance.session_created',$u,(int)$r['owner_organisation_id'],(string)$id,'training',null,null,$policy);return $id;});}
 public static function get(\PDO $p,int $id):array {ExtendedMigrations::require($p);$s=Database::query($p,'SELECT * FROM training_sessions WHERE id=?',[$id])->fetch();if(!$s)throw new \RuntimeException('Sesi tidak wujud.');Policy::programme($p,(int)$s['programme_id']);return $s;}
 public static function checkpoint(\PDO $p,int $u,int $session,string $title,string $opens,string $closes):int {return Core::tx($p,function()use($p,$u,$session,$title,$opens,$closes){$s=self::get($p,$session);$r=Policy::programme($p,(int)$s['programme_id'],true);Policy::require($p,$u,'attendance.manage',$r);if(Database::query($p,'SELECT 1 FROM training_attendance_events WHERE session_id=?',[$session])->fetchColumn())throw new \RuntimeException('Polisi sesi dikunci selepas event pertama.');$opens=Workflow::date($opens);$closes=Workflow::date($closes);if($opens<$s['start_at']||$closes>$s['end_at']||$opens>=$closes)throw new \RuntimeException('Window checkpoint tidak sah.');Database::query($p,'INSERT INTO training_checkpoints(session_id,title,opens_at,closes_at) VALUES(?,?,?,?)',[$session,Core::text($title),$opens,$closes]);return (int)$p->lastInsertId();});}
 public static function token(\PDO $p,int $u,int $session,string $action,int $ttl,?int $checkpoint=null,?int $staff=null,?string $binding=null):string {return Core::tx($p,function()use($p,$u,$session,$action,$ttl,$checkpoint,$staff,$binding){$s=self::get($p,$session);$r=Policy::published($p,(int)$s['programme_id'],true);if(!in_array($action,['CHECK_IN','CHECK_OUT','CHECKPOINT'],true)||$ttl<1||$ttl>900)throw new \RuntimeException('Action/TTL tidak sah.');if($staff===null)Policy::require($p,$u,'attendance.manage',$r);else{$a=Policy::actor($p,$u);if((int)$a['staff_identity_id']!==$staff||!is_string($binding)||strlen($binding)<32)throw new \RuntimeException('Personal QR perlu session binding sendiri.');$reg=Database::query($p,"SELECT id FROM training_registrations WHERE programme_id=? AND staff_identity_id=? AND status='CONFIRMED'",[$r['id'],$staff])->fetchColumn();if(!$reg)throw new \RuntimeException('Pendaftaran diperlukan.');}
 if($action==='CHECKPOINT'){if(!$checkpoint||!Database::query($p,'SELECT 1 FROM training_checkpoints WHERE id=? AND session_id=?',[$checkpoint,$session])->fetchColumn())throw new \RuntimeException('Checkpoint tidak sepadan.');}elseif($checkpoint!==null)throw new \RuntimeException('Checkpoint tidak sah.');$t=bin2hex(random_bytes(16));Database::query($p,'INSERT INTO training_attendance_tokens(session_id,checkpoint_id,action,token_hash,staff_identity_id,expires_at,session_binding,issued_by) VALUES(?,?,?,?,?,DATE_ADD(UTC_TIMESTAMP(),INTERVAL ? SECOND),?,?)',[$session,$checkpoint,$action,hash('sha256',$t),$staff,$ttl,$binding?hash('sha256',$binding):null,$u]);return $t;});}
 public static function scan(\PDO $p,int $u,string $token,?string $binding=null):int {if(!preg_match('/\A[a-f0-9]{32}\z/',$token))throw new \RuntimeException('QR tidak sah.');return Core::tx($p,function()use($p,$u,$token,$binding){$t=Database::query($p,'SELECT * FROM training_attendance_tokens WHERE token_hash=? FOR UPDATE',[hash('sha256',$token)])->fetch();if(!$t||$t['revoked_at']||$t['expires_at']<gmdate('Y-m-d H:i:s'))throw new \RuntimeException('QR tamat tempoh/dibatalkan.');$s=self::get($p,(int)$t['session_id']);$r=Policy::published($p,(int)$s['programme_id'],true);$a=Policy::actor($p,$u);$staff=(int)$a['staff_identity_id'];if($t['staff_identity_id']){Policy::require($p,$u,'attendance.manage',$r);if(!hash_equals($t['session_binding'],hash('sha256',$binding??'')))throw new \RuntimeException('Session binding tidak sepadan.');$staff=(int)$t['staff_identity_id'];}$reg=Database::query($p,"SELECT * FROM training_registrations WHERE programme_id=? AND staff_identity_id=? AND status='CONFIRMED'",[$r['id'],$staff])->fetch();if(!$reg)throw new \RuntimeException('Pendaftaran confirmed diperlukan.');Registration::eligibility($p,$r,Policy::config($p,$r,true),Registration::snapshot($p,$staff));$id=self::event($p,$u,$s,$reg,$t['action'],(int)($t['checkpoint_id']??0),gmdate('Y-m-d H:i:s'),'QR',null,null);if($t['staff_identity_id'])Database::query($p,'UPDATE training_attendance_tokens SET revoked_at=UTC_TIMESTAMP() WHERE id=?',[$t['id']]);return $id;});}
 public static function manual(\PDO $p,int $u,int $session,int $registration,string $action,string $at,string $reason,string $notes,?int $checkpoint=null):int {return Core::tx($p,function()use($p,$u,$session,$registration,$action,$at,$reason,$notes,$checkpoint){$s=self::get($p,$session);$r=Policy::published($p,(int)$s['programme_id'],true);Policy::require($p,$u,'attendance.manage',$r);$reg=Workflow::registration($p,$u,(int)$r['id'],$registration,'attendance.manage');if(Workflow::date($at)>gmdate('Y-m-d H:i:s'))throw new \RuntimeException('Manual timestamp tidak boleh future.');Registration::eligibility($p,$r,Policy::config($p,$r,true),Registration::snapshot($p,(int)$reg['staff_identity_id']));return self::event($p,$u,$s,$reg,$action,$checkpoint??0,Workflow::date($at),'MANUAL',Core::text($reason,500),Core::text($notes,1000));});}
 private static function event(\PDO $p,int $u,array $s,array $reg,string $action,int $checkpoint,string $at,string $source,?string $reason,?string $notes):int {if(!in_array($action,['CHECK_IN','CHECK_OUT','CHECKPOINT'],true))throw new \RuntimeException('Action tidak sah.');$policy=json_decode($s['policy_json'],true);$first=Database::query($p,"SELECT * FROM training_attendance_events WHERE session_id=? AND registration_id=? AND action='CHECK_IN' FOR UPDATE",[$s['id'],$reg['id']])->fetch();if($at<gmdate('Y-m-d H:i:s',strtotime($s['start_at'].' UTC')-(int)$policy['early_minutes']*60)||$at>gmdate('Y-m-d H:i:s',strtotime($s['end_at'].' UTC')+(int)$policy['checkout_grace_minutes']*60))throw new \RuntimeException('Attendance di luar window.');if($action!=='CHECK_IN'&&(!$first||$at<$first['happened_at']))throw new \RuntimeException('Check-in dahulu.');if($action==='CHECKPOINT'){$cp=Database::query($p,'SELECT * FROM training_checkpoints WHERE id=? AND session_id=?',[$checkpoint,$s['id']])->fetch();if(!$cp||$at<$cp['opens_at']||$at>$cp['closes_at'])throw new \RuntimeException('Checkpoint di luar window.');}elseif($checkpoint!==0)throw new \RuntimeException('Checkpoint action tidak sepadan.');if($action!=='CHECK_OUT'&&Database::query($p,"SELECT 1 FROM training_attendance_events WHERE session_id=? AND registration_id=? AND action='CHECK_OUT'",[$s['id'],$reg['id']])->fetchColumn())throw new \RuntimeException('Sesi telah checkout.');Database::query($p,'INSERT INTO training_attendance_events(session_id,registration_id,action,checkpoint_key,happened_at,original_at,source,actor_id,reason,notes) VALUES(?,?,?,?,?,?,?,?,?,?)',[$s['id'],$reg['id'],$action,$checkpoint,$at,$at,$source,$u,$reason,$notes]);$id=(int)$p->lastInsertId();$r=Policy::programme($p,(int)$s['programme_id']);Audit::record($p,'attendance.recorded',$u,(int)$r['owner_organisation_id'],(string)$id,'training',$reason,null,['action'=>$action,'source'=>$source,'at'=>$at,'registration'=>$reg['id']]);return $id;}
 public static function status(\PDO $p,int $u,int $session,int $registration):array {$s=self::get($p,$session);Workflow::registration($p,$u,(int)$s['programme_id'],$registration,'attendance.view');$rows=Database::query($p,'SELECT * FROM training_attendance_events WHERE session_id=? AND registration_id=?',[$session,$registration])->fetchAll();$in=null;$out=null;$cps=[];foreach($rows as $e){if($e['action']==='CHECK_IN')$in=$e['happened_at'];if($e['action']==='CHECK_OUT')$out=$e['happened_at'];if($e['action']==='CHECKPOINT')$cps[]=(int)$e['checkpoint_key'];}$c=json_decode($s['policy_json'],true);$late=$in?max(0,(strtotime($in.' UTC')-strtotime($s['start_at'].' UTC'))/60):null;$arrival=$late===null?(gmdate('Y-m-d H:i:s')<$s['start_at']?'NOT_STARTED':'ABSENT'):($late>$c['too_late_minutes']?'TOO_LATE':($late>$c['late_minutes']?'LATE':($late>$c['grace_minutes']?'AFTER_GRACE':'ON_TIME')));$minutes=$in&&$out?max(0,(min(strtotime($out.' UTC'),strtotime($s['end_at'].' UTC'))-max(strtotime($in.' UTC'),strtotime($s['start_at'].' UTC')))/60):0;$required=array_map('intval',Database::query($p,'SELECT id FROM training_checkpoints WHERE session_id=?',[$session])->fetchAll(\PDO::FETCH_COLUMN));$completed=$in&&$out&&!array_diff($required,$cps)&&$minutes>=$c['minimum_minutes']&&($arrival!=='LATE'||$c['allow_late_completion'])&&($arrival!=='TOO_LATE'||$c['allow_too_late_completion']);return ['arrival'=>$arrival,'minutes'=>$minutes,'completed'=>(bool)$completed,'status'=>$completed?'ATTENDANCE_COMPLETED':($in?'INCOMPLETE':($arrival==='NOT_STARTED'?'NOT_STARTED':'ABSENT')),'checkpoints'=>$cps];}
 public static function complete(\PDO $p,int $u,int $programme,int $rid):bool {$sessions=Database::query($p,'SELECT id FROM training_sessions WHERE programme_id=?',[$programme])->fetchAll();if(!$sessions)return false;foreach($sessions as $s)if(!self::status($p,$u,(int)$s['id'],$rid)['completed'])return false;return true;}
 public static function correction(\PDO $p,int $u,int $event,string $at,string $reason,string $notes):int {return Core::tx($p,function()use($p,$u,$event,$at,$reason,$notes){$e=Database::query($p,'SELECT e.*,s.programme_id FROM training_attendance_events e JOIN training_sessions s ON s.id=e.session_id WHERE e.id=? FOR UPDATE',[$event])->fetch();if(!$e)throw new \RuntimeException('Event tidak wujud.');Policy::require($p,$u,'attendance.correct',Policy::programme($p,(int)$e['programme_id'],true));Database::query($p,'INSERT INTO training_attendance_corrections(event_id,requested_by,proposed_at,previous_at,reason,notes) VALUES(?,?,?,?,?,?)',[$event,$u,Workflow::date($at),$e['happened_at'],Core::text($reason,500),Core::text($notes,1000)]);$id=(int)$p->lastInsertId();$r=Policy::programme($p,(int)$e['programme_id']);Audit::record($p,'attendance.correction_requested',$u,(int)$r['owner_organisation_id'],(string)$id,'training',$reason,['at'=>$e['happened_at']],['at'=>$at]);return $id;});}
 public static function review(\PDO $p,int $u,int $id,bool $approve):void {Core::tx($p,function()use($p,$u,$id,$approve){$c=Database::query($p,'SELECT c.*,e.session_id,e.action,e.checkpoint_key,e.registration_id,s.programme_id,s.start_at,s.end_at FROM training_attendance_corrections c JOIN training_attendance_events e ON e.id=c.event_id JOIN training_sessions s ON s.id=e.session_id WHERE c.id=? FOR UPDATE',[$id])->fetch();if(!$c||$c['status']!=='PENDING')throw new \RuntimeException('Correction bukan pending.');$r=Policy::programme($p,(int)$c['programme_id'],true);Policy::require($p,$u,'attendance.correct',$r);Workflow::reviewer($p,$u,(int)$c['requested_by']);if($approve){if($c['proposed_at']<$c['start_at']||$c['proposed_at']>$c['end_at']||$c['proposed_at']>gmdate('Y-m-d H:i:s'))throw new \RuntimeException('Correction di luar sesi.');if(Database::query($p,"SELECT 1 FROM training_outputs WHERE registration_id=? AND kind='CERTIFICATE' AND status='LOCKED' UNION SELECT 1 FROM training_cpd_records WHERE registration_id=? AND status='APPROVED'",[$c['registration_id'],$c['registration_id']])->fetchColumn())throw new \RuntimeException('Final records exist: void/reissue dahulu.');if($c['action']==='CHECKPOINT'){$cp=Database::query($p,'SELECT opens_at,closes_at FROM training_checkpoints WHERE id=?',[$c['checkpoint_key']])->fetch();if(!$cp||$c['proposed_at']<$cp['opens_at']||$c['proposed_at']>$cp['closes_at'])throw new \RuntimeException('Correction di luar checkpoint window.');}foreach(Database::query($p,'SELECT id,action,happened_at FROM training_attendance_events WHERE session_id=? AND registration_id=? FOR UPDATE',[$c['session_id'],$c['registration_id']])->fetchAll() as $event){if($event['id']==$c['event_id'])continue;if($c['action']==='CHECK_IN'&&$event['happened_at']<$c['proposed_at']||$c['action']==='CHECK_OUT'&&$event['happened_at']>$c['proposed_at']||$c['action']==='CHECKPOINT'&&($event['action']==='CHECK_IN'&&$event['happened_at']>$c['proposed_at']||$event['action']==='CHECK_OUT'&&$event['happened_at']<$c['proposed_at']))throw new \RuntimeException('Correction melanggar turutan event.');}$current=Database::query($p,'SELECT happened_at FROM training_attendance_events WHERE id=? FOR UPDATE',[$c['event_id']])->fetchColumn();if($current!==$c['previous_at'])throw new \RuntimeException('Stale correction; semak semula.');Database::query($p,'UPDATE training_attendance_events SET happened_at=? WHERE id=?',[$c['proposed_at'],$c['event_id']]);}Database::query($p,'UPDATE training_attendance_corrections SET status=?,reviewed_by=?,reviewed_at=UTC_TIMESTAMP() WHERE id=?',[$approve?'APPROVED':'REJECTED',$u,$id]);Audit::record($p,'attendance.correction_reviewed',$u,(int)$r['owner_organisation_id'],(string)$id,'training',$c['reason'],['at'=>$c['previous_at']],['at'=>$c['proposed_at'],'approved'=>$approve]);});}
}
